+const FNV_PRIME: u64 = 0x100000001b3;
+
+/// Same result as `FnvHasher::with_key(hash_index)` followed by `write(slice)`,
+/// processing four bytes per loop iteration.
+fn slice_hash(slice: &[u8], hash_index: u64) -> u64 {
+    let mut hash = hash_index;
+    let mut rest = slice;
+    while let [a, b, c, d, tail @ ..] = rest {
+        hash = (hash ^ u64::from(*a)).wrapping_mul(FNV_PRIME);
+        hash = (hash ^ u64::from(*b)).wrapping_mul(FNV_PRIME);
+        hash = (hash ^ u64::from(*c)).wrapping_mul(FNV_PRIME);
+        hash = (hash ^ u64::from(*d)).wrapping_mul(FNV_PRIME);
+        rest = tail;
+    }
+    for byte in rest {
+        hash = (hash ^ u64::from(*byte)).wrapping_mul(FNV_PRIME);
+    }
+    hash
+}

